-- Marcaciones y clima laboral de PRUEBA del 1 al 13 de octubre de 2026 para la empresa «Demo» de
-- producción con NIT 901123456 (cmsvhm2jn00l41146esg4o6y0, la de demo@horapro.co). Pedido del dueño el 14 de
-- octubre de 2026. NO es la otra «Demo» (NIT 2872837), que tiene el clima de septiembre.
--
-- Lo generó backend/prisma/generar-demo-clima-octubre.mjs, con semilla fija: no editarlo a mano.
-- Todo lo que agrega lleva «demooct-» en el id; el bloque BORRAR lo quita entero.
--
-- Qué agrega:
--   - Días esperados del 1 al 13 de octubre para las 6 personas de prueba (copiados de Samir), SOLO los
--     que les falten: si la aplicación ya los creó, no se tocan.
--   - 125 marcaciones de los días hábiles del 1 al 13 (el 12 es festivo: solo Julián, como
--     FESTIVO), con salida al almuerzo. Son las salidas contra las que el panel mide «Respondieron».
--   - 57 caritas con motivos y 10 observaciones con nombre. Cada persona cuenta algo distinto
--     (carita por día, «-» sin responder, «F» falta): ar 34-23434 · sa 455-454F · 01 55454554 · 02 43322121 · 03 21234455 · 04 3-34F33- · 05 44212-11 · 06 54434454
--   - 8 notas del buzón confidencial, con autor FALSO ('demo:sin-autor').
--   - 3 casos de seguimiento: Andrés EN SEGUIMIENTO (desde el 6), Daniela SIN REVISAR (desde el
--     5) y Valentina CERRADO (desde el 1), con comentarios del primer usuario de la empresa.

-- ============================================================================
-- AGREGAR (un solo envío)
-- ============================================================================
INSERT INTO dias_esperados (id, colaboradorId, fecha, programado, horaEntrada, horaSalida, toleranciaMin, almuerzoMin, minutosEsperados, horarioId, origen, creadoEn, actualizadoEn, toleranciaSalidaMin, ajustaEntrada, almuerzoInicio, almuerzoFin, descansos, plantillaId, esDescanso, descansoPintado) SELECT CONCAT('demooct-d-', SUBSTRING(c.id, 14, 2), '-', DATE_FORMAT(d.fecha, '%m%d')), c.id, d.fecha, d.programado, d.horaEntrada, d.horaSalida, d.toleranciaMin, d.almuerzoMin, d.minutosEsperados, d.horarioId, d.origen, '2026-10-14 12:00:00.000', '2026-10-14 12:00:00.000', d.toleranciaSalidaMin, d.ajustaEntrada, d.almuerzoInicio, d.almuerzoFin, d.descansos, d.plantillaId, d.esDescanso, d.descansoPintado FROM dias_esperados d CROSS JOIN colaboradores c WHERE d.colaboradorId = 'cmt3sq303019e1146irw2bmlo' AND d.fecha >= '2026-10-01 05:00:00.000' AND d.fecha < '2026-10-14 05:00:00.000' AND c.empresaId = 'cmsvhm2jn00l41146esg4o6y0' AND c.id LIKE 'demosept-col-%' AND NOT EXISTS (SELECT 1 FROM dias_esperados x WHERE x.colaboradorId = c.id AND x.fecha = d.fecha);
