INSERT INTO observaciones_confidenciales (id, empresaId, semana, visibleDesde, texto, autorCifrado) VALUES ('demooct-nota-01', 'cmsvhm2jn00l41146esg4o6y0', '2026-09-28 05:00:00.000', '2026-10-02 05:00:00.000', 'Siento que hay preferencias a la hora de dar los permisos.', 'demo:sin-autor'), ('demooct-nota-02', 'cmsvhm2jn00l41146esg4o6y0', '2026-09-28 05:00:00.000', '2026-10-03 05:00:00.000', 'Gracias por el detalle de cumpleaños, se sintió bonito.', 'demo:sin-autor'), ('demooct-nota-03', 'cmsvhm2jn00l41146esg4o6y0', '2026-10-05 05:00:00.000', '2026-10-06 05:00:00.000', 'El ambiente en la bodega está muy pesado últimamente.', 'demo:sin-autor'), ('demooct-nota-04', 'cmsvhm2jn00l41146esg4o6y0', '2026-10-05 05:00:00.000', '2026-10-08 05:00:00.000', 'Me gustaría recibir capacitación en el sistema nuevo.', 'demo:sin-autor'), ('demooct-nota-05', 'cmsvhm2jn00l41146esg4o6y0', '2026-10-05 05:00:00.000', '2026-10-09 05:00:00.000', 'Hay un compañero que siempre llega tarde y nadie le dice nada.', 'demo:sin-autor'), ('demooct-nota-06', 'cmsvhm2jn00l41146esg4o6y0', '2026-10-05 05:00:00.000', '2026-10-10 05:00:00.000', 'Las sillas de la oficina están dañadas y duele la espalda.', 'demo:sin-autor'), ('demooct-nota-07', 'cmsvhm2jn00l41146esg4o6y0', '2026-10-12 05:00:00.000', '2026-10-14 05:00:00.000', 'Me preocupa que no nos estén pagando completas las horas extra.', 'demo:sin-autor'), ('demooct-nota-08', 'cmsvhm2jn00l41146esg4o6y0', '2026-10-12 05:00:00.000', '2026-10-14 05:00:00.000', 'El jefe de bodega grita mucho, da miedo decirle algo.', 'demo:sin-autor');
INSERT INTO seguimientos_clima (id, empresaId, colaboradorId, desde, estado, responsableId, abiertoEn, cerradoEn, actualizadoEn) SELECT 'demooct-s-02', 'cmsvhm2jn00l41146esg4o6y0', 'demosept-col-02', '2026-10-06 05:00:00.000', 'EN_SEGUIMIENTO', (SELECT u.id FROM usuarios u WHERE u.empresaId = 'cmsvhm2jn00l41146esg4o6y0' ORDER BY u.creadoEn LIMIT 1), '2026-10-09 14:12:00.000', NULL, '2026-10-10 21:40:00.000' UNION ALL SELECT 'demooct-s-05', 'cmsvhm2jn00l41146esg4o6y0', 'demosept-col-05', '2026-10-05 05:00:00.000', 'SIN_REVISAR', NULL, '2026-10-13 23:05:00.000', NULL, '2026-10-13 23:05:00.000' UNION ALL SELECT 'demooct-s-03', 'cmsvhm2jn00l41146esg4o6y0', 'demosept-col-03', '2026-10-01 05:00:00.000', 'CERRADO', (SELECT u.id FROM usuarios u WHERE u.empresaId = 'cmsvhm2jn00l41146esg4o6y0' ORDER BY u.creadoEn LIMIT 1), '2026-10-05 23:30:00.000', '2026-10-09 16:00:00.000', '2026-10-09 16:00:00.000';
INSERT INTO comentarios_seguimiento_clima (id, seguimientoId, autorId, autorNombre, texto, creadoEn) SELECT 'demooct-k-01', 'demooct-s-02', (SELECT u.id FROM usuarios u WHERE u.empresaId = 'cmsvhm2jn00l41146esg4o6y0' ORDER BY u.creadoEn LIMIT 1), (SELECT u.nombre FROM usuarios u WHERE u.empresaId = 'cmsvhm2jn00l41146esg4o6y0' ORDER BY u.creadoEn LIMIT 1), 'Hablé con Andrés: dice que lo están dejando solo en la bodega en las tardes.', '2026-10-09 14:15:00.000' UNION ALL SELECT 'demooct-k-02', 'demooct-s-02', (SELECT u.id FROM usuarios u WHERE u.empresaId = 'cmsvhm2jn00l41146esg4o6y0' ORDER BY u.creadoEn LIMIT 1), (SELECT u.nombre FROM usuarios u WHERE u.empresaId = 'cmsvhm2jn00l41146esg4o6y0' ORDER BY u.creadoEn LIMIT 1), 'Se le asignó un apoyo para descargar los martes y jueves. Revisar la próxima semana.', '2026-10-10 21:40:00.000' UNION ALL SELECT 'demooct-k-03', 'demooct-s-03', (SELECT u.id FROM usuarios u WHERE u.empresaId = 'cmsvhm2jn00l41146esg4o6y0' ORDER BY u.creadoEn LIMIT 1), (SELECT u.nombre FROM usuarios u WHERE u.empresaId = 'cmsvhm2jn00l41146esg4o6y0' ORDER BY u.creadoEn LIMIT 1), 'Valentina tuvo un roce con un compañero; se habló con los dos.', '2026-10-06 15:00:00.000' UNION ALL SELECT 'demooct-k-04', 'demooct-s-03', (SELECT u.id FROM usuarios u WHERE u.empresaId = 'cmsvhm2jn00l41146esg4o6y0' ORDER BY u.creadoEn LIMIT 1), (SELECT u.nombre FROM usuarios u WHERE u.empresaId = 'cmsvhm2jn00l41146esg4o6y0' ORDER BY u.creadoEn LIMIT 1), 'Ya está bien, sus últimas respuestas son buenas. Se cierra el caso.', '2026-10-09 16:00:00.000';

