SELECT (SELECT COUNT(*) FROM dias_esperados WHERE id LIKE 'demooct-d-%') AS dias, (SELECT COUNT(*) FROM registros WHERE id LIKE 'demooct-r-%') AS marcaciones, (SELECT COUNT(*) FROM calificaciones_clima WHERE id LIKE 'demooct-c-%') AS caritas, (SELECT COUNT(*) FROM calificaciones_clima WHERE id LIKE 'demooct-c-%' AND observacion IS NOT NULL) AS observaciones, (SELECT COUNT(*) FROM observaciones_confidenciales WHERE id LIKE 'demooct-nota-%') AS notas, (SELECT COUNT(*) FROM seguimientos_clima WHERE id LIKE 'demooct-s-%') AS casos, (SELECT COUNT(*) FROM comentarios_seguimiento_clima WHERE id LIKE 'demooct-k-%') AS comentarios;

